<script setup lang="ts">
import{ref,onMounted}from'vue';import{api}from'../app/api';import Icon from'../ui/Icon.vue';const props=defineProps<{invite:string}>();const emit=defineEmits<{login:[user:any,trip?:string]}>();const name=ref(''),password=ref(''),error=ref(''),busy=ref(false),title=ref(''),existing=ref(false);onMounted(async()=>{if(props.invite)try{title.value=(await api('/invites/preview','POST',{token:props.invite})).title}catch(e){error.value=(e as Error).message}});async function submit(){busy.value=true;error.value='';try{if(props.invite&&!existing.value){const r=await api('/invites/accept','POST',{token:props.invite,username:name.value,password:password.value});history.replaceState(null,'',location.pathname);emit('login',r.user,r.tripId)}else{const user=await api('/session','POST',{username:name.value,password:password.value});if(props.invite){const r=await api('/invites/accept','POST',{token:props.invite});history.replaceState(null,'',location.pathname);emit('login',user,r.tripId)}else emit('login',user)}}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><main class="login-page"><div class="login-story"><div class="brand"><span class="brand-mark"><Icon name="map" :size="26"/></span>行间 <small>一起去看看</small></div><div><span class="eyebrow">A LITTLE PLANNING. A GREAT JOURNEY.</span><h1>下一站，<br>和你一起。</h1><p>把想去的地方连成路线，<br>把路上的琐事，变成两个人的默契。</p><div class="story-route"><span>想去的地方</span><i></i><span>一起规划</span><i></i><span>出发</span></div></div><small>规划 · 交通 · 随身物品</small></div><section class="login-card"><span class="eyebrow">行间旅行</span><h2>{{invite?'一起加入旅行':'欢迎回来'}}</h2><p class="muted">{{invite?`同行人邀请你规划「${title||'旅行'}」`:'登录，继续安排下一段旅程。'}}</p><form @submit.prevent="submit"><label>用户名<input v-model="name" autocomplete="username" required minlength="2" maxlength="32"></label><label>密码<input v-model="password" type="password" :autocomplete="invite&&!existing?'new-password':'current-password'" required minlength="12" maxlength="128"></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary full" :disabled="busy">{{busy?'请稍候…':invite&&!existing?'创建账号并加入':'登录'}}</button></form><button v-if="invite" class="text-button" @click="existing=!existing">{{existing?'创建新账号加入':'已有账号？登录后加入'}}</button><p class="login-note">{{invite?'邀请仅供一次使用，旅行内容仅同行人可见。':'私人工作区 · 首次使用请由工作区拥有者创建账号或发送邀请。'}}</p></section></main></template>
